def web(specs,path,title,style):
    s=['<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+'</title><style>'+style+'</style><nav><a href="index.html">Материалы</a><a href="assignment.html">Методика</a><a href="areas.html">Варианты</a></nav>']
    for page in specs:
        s.append('<article><header><small>ПП ПМ.06 · ДКИП-4ХХ</small><h1>'+E(page['title'])+'</h1></header><div class="content">')
        for i,x in enumerate(page['blocks'],1):
            s.append('<div class="step"><div class="num">'+str(i)+'</div><section class="block"><h2>'+E(x['title'])+'</h2>')
            if x['kind']=='code':s.append('<pre>'+E(x['text'])+'</pre>')
            elif x['kind']=='link':s.append('<a href="'+E(x['url'])+'">'+E(x['text'])+'</a>')
            elif x['kind']=='image':s.append('<figure><img src="'+E(x['path'])+'" alt="'+E(x['text'])+'"><figcaption>'+E(x['text'])+'</figcaption></figure>')
            else:s.extend('<p>'+E(y)+'</p>' for y in x['text'].split('\n\n'))
            s.append('</section></div>')
        s.append('</div></article>')
    path.write_text(''.join(s)+'</html>',encoding='utf-8')

def build():
    variants=json.loads((ROOT/'variants.json').read_text(encoding='utf-8'));areas=[]
    for v in variants:
        n=v['variant'];a,c,d=v['ids'];end=v['end']
        areas.append(p('Вариант '+n+' — '+v['domain'],
         b('Собственная работа и исходные данные',f'Сопроводить готовый учебный журнал своей области. Конкретизировать организацию и операцию в паспорте. ID {a}, {c}, {d}: соответственно день до границы, на границе и после. Конечная дата: {end}. Журнал моделирует часть ИС предприятия.'),
         link('Скачать стенд варианта '+n,f'v{n}.zip'),
         b('Первое действие и маршрут',f'Распаковать v{n}.zip; запустить по п. 3.1 методики. Сверить номер, область, ID. Выполнить паспорт → роли/RACI/процессы/SLA → инцидент → контрпример → изменение → восстановление → метрики → сдачу. Образец 01 показывает способ; выполнять только свой вариант.'),
         b('Индивидуальные условия и ожидание',f'В запросе end={end} по контракту ожидаются [{a},{c}], исходный дефект даёт только [{a}]. После исправления перенести запись {d} на {end}; ожидать [{a},{c},{d}]. Вернуть исходную дату и ожидание двух ID. Предел реакции: {v["reaction_minutes"]} мин; восстановления: {v["recovery_minutes"]} мин. Объявить рабочее окно, обосновать критичность и сравнить с реальными UTC-событиями, не подставляя условные времена.'),
         b('Проверка и доказательства','INC-01/INC-02/REQ-03, код до/после, FAIL→PASS, коллекции, копия/хеши/восстановление, события/расчёты и чистый повтор. В отчёте — паспорт, RACI, 14 процессов, шесть схем, собственные снимки и ссылка репозитория; приложить README, инструкцию и формы по п. 3.27. Проверять состав данных, а не только HTTP 200.')))
    # The exact responsible expression remains readable independently of the UI image.
    change_page=next(x for x in guide if x['title']=='3. Методика — изменение и откат')
    change_page['blocks'].insert(2,code('Условие до и после','До: датаЗаписи < end\nПосле: датаЗаписи <= end\n\nВ Program.cs датаЗаписи вычисляется выражением:\nDateOnly.ParseExact(e.Date,"yyyy-MM-dd",\n    CultureInfo.InvariantCulture)'))
    data=dict(assignment=assignment,guide=guide,areas=areas)
    (ROOT/'content').mkdir(exist_ok=True);(ROOT/'content/materials.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
    render_approved.build(ROOT,data)
    # Reuse only approved typography/geometry; no other cohort's task content.
    style=(ROOT/'assets/style.css').read_text(encoding='utf-8')
    web(assignment+guide,ROOT/'assignment.html','Задание и методические рекомендации',style);web(areas,ROOT/'areas.html','Список предметных областей',style)
    links=[('Задание и методические рекомендации','assignment.pdf'),('Список предметных областей','guide.pdf'),('Отчет о выполнении.docx','%D0%9E%D1%82%D1%87%D0%B5%D1%82%20%D0%BE%20%D0%B2%D1%8B%D0%BF%D0%BE%D0%BB%D0%BD%D0%B5%D0%BD%D0%B8%D0%B8.docx'),('Тестовый проект — HTTP-коллекция','test-project.zip')]
    md='# Сопровождение информационных систем\n\nПП ПМ.06 · ДКИП-4ХХ\n\n'+'\n'.join('- ['+label+']('+BASE+f+')' for label,f in links)+'\n'
    (ROOT/'README.md').write_text(md,encoding='utf-8');(ROOT/'docs/index.md').write_text(md,encoding='utf-8')
    (ROOT/'docs/assignment.md').write_text('# Задание и методические рекомендации\n\n[Полный документ]('+BASE+'assignment.pdf)\n\n[Тестовый проект — HTTP-коллекция]('+BASE+'test-project.zip)\n',encoding='utf-8')
    (ROOT/'docs/areas.md').write_text('# Список предметных областей\n\n[Полный список]('+BASE+'guide.pdf)\n\n'+'\n'.join('- '+v['variant']+'. '+v['domain']+' — [Скачать свой стенд]('+BASE+'v'+v['variant']+'.zip)' for v in variants)+'\n',encoding='utf-8')
    for i in range(1,5):
        file=ROOT/f'docs/practice/stage{i}.md';text=file.read_text(encoding='utf-8');text=re.sub(r'\*\*10 процессов\*\*','**14 процессов**',text);prefix='[Актуальное полное задание и выполняемый маршрут]('+BASE+'assignment.pdf). Ниже сохранён дополнительный разбор учебной модели; его ситуации не являются наблюдениями на предприятии.\n\n';text=prefix+text.removeprefix(prefix);file.write_text(text,encoding='utf-8')
    (ROOT/'index.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Сопровождение информационных систем</title><style>'+style+'</style><article><header><small>ПП ПМ.06 · ДКИП-4ХХ</small><h1>Сопровождение информационных систем</h1></header><div class="content"><p><a href="assignment.html">Открыть методику</a> · <a href="areas.html">Открыть варианты</a></p><ul>'+''.join('<li><a href="'+BASE+f+'">'+E(label)+'</a></li>' for label,f in links)+'</ul></div></article></html>',encoding='utf-8')
    (ROOT/'mkdocs.yml').write_text('site_name: ПП ПМ.06 Сопровождение информационных систем\nsite_url: https://olgakraven.github.io/DKIP.PP.PM.06-method8cem/\ndocs_dir: docs\nnav:\n  - Материалы: index.md\n  - Методика: assignment.md\n  - Варианты: areas.md\n',encoding='utf-8')
    print('Built self-contained route and',len(areas),'variant cards')
if __name__=='__main__':build()
